import java.util.ArrayList;
import java.util.Scanner;

public class P851C {
    static final double EPS = 1e-9;

    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int n = scan.nextInt();
        if (n > 11) {
            System.out.println(0);
            return;
        }
        int[][] pts = new int[n][5];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 5; j++) {
                pts[i][j] = scan.nextInt();
            }
        }
        ArrayList<Integer> ans = new ArrayList<>();
        int i = 0;
        while (i < n) {
            boolean good = true;
            int j = 0;
            outer:
            while (j < n) {
                if (j == i) {
                    j++;
                    continue;
                }
                int k = j + 1;
                while (k < n) {
                    if (k == i) {
                        k++;
                        continue;
                    }
                    int dot = 0;
                    double sq1 = 0;
                    double sq2 = 0;
                    for (int d = 0; d < 5; d++) {
                        int v1 = pts[j][d] - pts[i][d];
                        int v2 = pts[k][d] - pts[i][d];
                        dot += v1 * v2;
                        sq1 += v1 * v1;
                        sq2 += v2 * v2;
                    }
                    double angle = Math.acos(dot / (Math.sqrt(sq1) * Math.sqrt(sq2)));
                    if (angle < Math.PI / 2 - EPS) {
                        good = false;
                        break outer;
                    }
                    k++;
                }
                j++;
            }
            if (good) {
                ans.add(i + 1);
            }
            i++;
        }
        System.out.println(ans.size());
        for (int idx : ans) {
            System.out.println(idx);
        }
    }
}
